	title = "The Barrow Deeps",
	aliases = { "Barrow Deeps" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Barrow Deeps sind die tiefsten Bereiche der Grabhügel der {link:night-elves}Nachtelfen{/link}, weit unter den Hügeln, in denen ihre Druiden schliefen. Die Kaldorei gruben sie nicht für die Lebenden. Zehntausend Jahre lang hielten sie einen einzigen Gefangenen: {link:illidan-stormrage}Illidan Stormrage{/link}, den Verräter. Nur wenige stiegen in sie hinab, und noch weniger sprachen von dem, was sie gesehen hatten. Nun ist ihr Schweigen gebrochen, und nur eine kleine, abgehärtete Schar darf hoffen, sie zu durchschreiten.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Die Grabhügel wurden für die Druiden von {link:malfurion-stormrage}Malfurion Stormrage{/link} angelegt. Nach dem {link:war-of-the-ancients}Krieg der Ahnen{/link} gaben sich die Druiden einem langen Schlaf hin. Ihre Geister wanderten durch den {link:emerald-dream}Smaragdgrünen Traum{/link}, während ihre Körper in Hallen aus Wurzeln und Stein ruhten. Unter ihnen schliefen die Druiden der Klaue, Druiden, die die Gestalt des großen Bären annehmen konnten.

Noch tiefer lag ein finstereres Werk. Als {link:illidan-stormrage}Illidan{/link} einen neuen Brunnen auf dem {link:mount-hyjal}Berg Hyjal{/link} schuf, sah Malfurion darin ein Verbrechen an der Welt. Er ließ seinen Bruder unter der Erde anketten, in einem Gefängnis unterhalb der Grabhügel. Maiev Shadowsong und ihre Wächterinnen wurden eingesetzt, um ihn dort festzuhalten, und sie hielten ihn zehntausend Jahre lang fest. In all dieser Zeit schliefen die Druiden in den Hügeln über ihm weiter.]=],
		},
		{
			title = "Der Dritte Krieg",
			text = [=[Als die {link:burning-legion}Brennende Legion{/link} zurückkehrte, weckte {link:tyrande-whisperwind}Tyrande Whisperwind{/link} die schlafenden Druiden, und die Druiden der Klaue erhoben sich aus ihren Hügeln, um zu kämpfen. Dann stieg Tyrande gegen den Willen ihres Geliebten in das Gefängnis hinab. Sie kämpfte sich an seinen Wächterinnen vorbei und befreite {link:illidan-stormrage}Illidan{/link}, weil sie glaubte, dass seine Macht gegen die Dämonen gebraucht wurde. {link:malfurion-stormrage}Malfurion{/link} verbannte seinen Bruder später aus den Wäldern der Kaldorei. Die Zelle unter den Grabhügeln blieb leer, und der Verräter kehrte nicht in sie zurück.]=],
		},
		{
			title = "In der Gegenwart",
			text = [=[Die Barrow Deeps sind kein stiller Ort mehr. Etwas regt sich in den dunklen Hallen unter den Hügeln, und die Pfade, die einst die Wächterinnen gingen, sind wieder gefährlich. Wer hinabsteigen will, muss zu wenigen sein und zu den Besten seiner Art gehören.]=],
